<?php

declare(strict_types=1);

namespace Qiick\ApiKeys;

/**
 * @internal Answers "is this domain a public suffix?" from Mozilla's Public Suffix List.
 *
 * Used to refuse origin wildcards such as `*.co.uk` or `*.github.io`, where
 * anyone can register a sibling and inherit the key's origin restriction. The
 * PRIVATE section (hosting platforms like github.io, vercel.app) counts, as it
 * does for browser cookies. Domains are compared in ASCII (punycode) form.
 *
 * ponytail: a snapshot of the list ships as `resources/public_suffix_list.php`
 * (MPL-2.0), regenerated by `scripts/update-public-suffix-list.php` before a
 * release. Suffixes added upstream after the snapshot are not refused until
 * the next refresh; the upgrade path is a scheduled refresh or
 * `jeremykendall/php-domain-parser`.
 */
final class PublicSuffixList
{
    public static function isPublicSuffix(string $domain): bool
    {
        // A plain array file: opcache keeps it as an immutable array, so a call pays a lookup, not a parse.
        /** @var array<string, true> $rules normal rules, `*.parent` wildcards and `!exceptions` */
        $rules = require __DIR__.'/../resources/public_suffix_list.php';

        $domain = strtolower($domain);

        if (isset($rules['!'.$domain])) {
            return false;
        }

        if (isset($rules[$domain])) {
            return true;
        }

        $labels = explode('.', $domain);

        // The list's implicit rule `*`: every top-level label is a public suffix.
        if (count($labels) === 1) {
            return true;
        }

        array_shift($labels);

        return isset($rules['*.'.implode('.', $labels)]);
    }
}
